// @zeus-internal
export type Point = { x: number; y: number };
/** Winding-number containment, including points on the boundary. */
export function inPolygon(point: Point, polygon: Point[]): boolean {
  if (polygon.length < 3) return false;
  let winding = 0;
  for (let index = 0; index < polygon.length; index++) {
    const start = polygon[index],
      end = polygon[(index + 1) % polygon.length];
    const cross = (end.x - start.x) * (point.y - start.y) - (point.x - start.x) * (end.y - start.y);
    if (
      Math.abs(cross) < 1e-8 &&
      point.x >= Math.min(start.x, end.x) &&
      point.x <= Math.max(start.x, end.x) &&
      point.y >= Math.min(start.y, end.y) &&
      point.y <= Math.max(start.y, end.y)
    )
      return true;
    if (start.y <= point.y && end.y > point.y && cross > 0) winding++;
    if (start.y > point.y && end.y <= point.y && cross < 0) winding--;
  }
  return winding !== 0;
}
